  function getTopChange(elm) {
    let index2 = 0;
    for (index2 = 0; index2 < changeList.length; index2++) {
      if (!changeList[index2].hasOwnProperty("revision")) {
        break;
      }
    }
    for (let idx2 = index2; idx2 >= 0; idx2--) {
      elm.append(`<div class="type"><h2 class="has-text-warning">v${changeList[idx2].version}${changeList[idx2].hasOwnProperty("revision") ? changeList[idx2].revision : ""}</h2><span class="has-text-caution">${changeList[idx2].date}</span></div>`);
      for (let i = 0; i < changeList[idx2].changes.length; i++) {
        elm.append(`<div class="desc condense">${changeList[idx2].changes[i]}</div>`);
      }
    }
    return elm;
  }

